(() => {
 const mode=document.body.dataset.page,type=mode==='portfolio'?'portfolio':mode==='story'?'news':null;if(!type){window.NEMO_RENDER?.layout(document.querySelector('#page-main')||document.body);return;}
 const data=window.NEMO_RAW,params=new URLSearchParams(location.search),key=type==='portfolio'?'project':'article',pool=type==='portfolio'?data.projects:data.stories,p=pool.find(p=>p.id===params.get(key))||(!params.has(key)?pool[0]:null);if(!p)return;
 const target=document.querySelector('.cms-document');window.NEMO_RENDER.layout(target);const bar=document.createElement('div');bar.className='cms-share';bar.innerHTML='<span id="cms-view-count"></span><button type="button" data-share="copy">링크 복사</button><button type="button" data-share="device">다른 앱으로 공유</button><a data-share="email">이메일</a><span class="cms-share-status" role="status"></span>';target.after(bar);
 const url=location.origin+location.pathname+'?'+key+'='+encodeURIComponent(p.id),status=bar.querySelector('[role="status"]');bar.querySelector('[data-share="email"]').href='mailto:?subject='+encodeURIComponent(p.title)+'&body='+encodeURIComponent(p.title+'\n'+url);
 const photos=[...new Set([p.visual,...window.NEMO_RENDER.blocks(p).filter(b=>b.type==='image').map(b=>b.src),...(p.images||[])].filter(Boolean))],dialog=document.createElement('dialog');dialog.className='cms-photo-dialog';dialog.setAttribute('aria-label','사진 크게 보기');dialog.innerHTML='<button type="button" data-photo-close aria-label="사진 닫기">×</button><div class="cms-full-photo"></div><div class="cms-photo-controls"><button type="button" data-photo-prev aria-label="이전 사진">←</button><span></span><button type="button" data-photo-next aria-label="다음 사진">→</button></div>';document.body.append(dialog);let photoIndex=0;
 const showPhoto=i=>{photoIndex=(i+photos.length)%photos.length;dialog.querySelector('.cms-full-photo').innerHTML=window.NEMO_RENDER.visual(photos[photoIndex],p.title);dialog.querySelector('.cms-photo-controls span').textContent=(photoIndex+1)+' / '+photos.length;};
 target.querySelectorAll('.cms-cover,.cms-block figure').forEach((el,i)=>{const src=el.matches('.cms-cover')?p.visual:window.NEMO_RENDER.blocks(p).filter(b=>b.type==='image')[i-1]?.src;el.tabIndex=0;el.setAttribute('role','button');el.setAttribute('aria-label','사진 크게 보기');const open=()=>{showPhoto(Math.max(0,photos.indexOf(src)));dialog.showModal();};el.addEventListener('click',open);el.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open();}});});
 dialog.querySelector('[data-photo-close]').addEventListener('click',()=>dialog.close());dialog.querySelector('[data-photo-prev]').addEventListener('click',()=>showPhoto(photoIndex-1));dialog.querySelector('[data-photo-next]').addEventListener('click',()=>showPhoto(photoIndex+1));dialog.addEventListener('keydown',event=>{if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();showPhoto(photoIndex+(event.key==='ArrowRight'?1:-1));}});
 bar.addEventListener('click',async event=>{const kind=event.target.dataset.share;if(!['copy','device'].includes(kind))return;try{if(kind==='device'&&navigator.share)await navigator.share({title:p.title,url});else{await navigator.clipboard.writeText(url);status.textContent=kind==='device'?'이 브라우저에서는 링크 복사로 공유해주세요.':'링크를 복사했어요.';}}catch(error){if(error.name!=='AbortError')status.textContent='주소창의 링크를 복사해주세요.';}});
 fetch('/api/public/view',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:p.id,type})}).then(r=>r.ok?r.json():null).then(data=>{if(data)bar.querySelector('#cms-view-count').textContent='조회 '+Number(data.views||0).toLocaleString('ko-KR');}).catch(()=>{});
})();
